#include <bits/stdc++.h>
using namespace std;

const long long MODULUS = 998244353;

long long power(long long base, long long exp) {
    long long result = 1;
    base %= MODULUS;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % MODULUS;
        }
        exp >>= 1;
        base = (base * base) % MODULUS;
    }
    return result;
}

long long choose(long long n, long long k) {
    long long num = 1;
    long long denom = 1;
    for (long long i = n - k + 1; i <= n; i++) {
        num = (num * i) % MODULUS;
    }
    for (long long i = 1; i <= k; i++) {
        denom = (denom * i) % MODULUS;
    }
    denom = power(denom, MODULUS - 2);
    return (num * denom) % MODULUS;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long kLong;
    cin >> n >> kLong;
    if (kLong >= n) {
        cout << "0\n";
    } else {
        int k = (int)kLong;
        int r = n - k;
        vector<long long> chooseArr(r + 1);
        chooseArr[0] = 1LL;
        long long numerator = 1LL;
        long long denominator = 1LL;
        for (int i = 1; i <= r; i++) {
            numerator = (numerator * (r + 1 - i)) % MODULUS;
            denominator = (denominator * i) % MODULUS;
            chooseArr[i] = (numerator * power(denominator, MODULUS - 2)) % MODULUS;
        }
        long long totalAns = 0;
        long long signFlag = 1;
        for (int i = 0; i <= r; i++) {
            long long term = power((long long)(r - i), (long long)n);
            totalAns += term * signFlag * chooseArr[i];
            totalAns %= MODULUS;
            signFlag = -signFlag;
        }
        totalAns = (totalAns * choose(n, k)) % MODULUS;
        if (k > 0) {
            totalAns = (totalAns * 2) % MODULUS;
        }
        if (totalAns < 0) {
            totalAns += MODULUS;
        }
        cout << totalAns << "\n";
    }
    return 0;
}
